import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Eye, EyeOff, ArrowRight, Leaf } from 'lucide-react';

function Signup() {
  const navigate = useNavigate();

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [form, setForm] = useState({
    fullName: '',
    email: '',
    password: '',
    confirmPassword: '',
    role: 'customer',
  });

  const [error, setError] = useState('');

  const handleChange = (event) => {
    const { name, value } = event.target;

    setForm((previous) => ({
      ...previous,
      [name]: value,
    }));
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    setError('');

    if (form.password.length < 8) {
      setError('Password must contain at least 8 characters.');
      return;
    }

    if (form.password !== form.confirmPassword) {
      setError('Passwords do not match.');
      return;
    }

    try {
      const user = {
        fullName: form.fullName.trim(),
        email: form.email.trim().toLowerCase(),
        role: form.role,
      };

      // Demo only: do not store the password in localStorage.
      localStorage.setItem('craftlanka_user', JSON.stringify(user));

      if (user.role === 'artisan') {
        navigate('/seller-dashboard');
      } else {
        navigate('/customer-dashboard');
      }
    } catch {
      setError('Unable to create your demo session. Please try again.');
    }
  };

  return (
    <main className="auth-page auth-signup-page">
      <section className="auth-card">
        <Link to="/" className="auth-brand">
          <span className="auth-brand-icon">✦</span>
          Craft<span>Lanka</span>
        </Link>

        <div className="auth-heading">
          <p className="eyebrow">JOIN OUR COMMUNITY</p>
          <h1>Create your <span>account.</span></h1>
          <p>
            Join a community celebrating Sri Lankan handmade crafts.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            Full Name
            <input
              type="text"
              name="fullName"
              placeholder="Enter your full name"
              value={form.fullName}
              onChange={handleChange}
              autoComplete="name"
              required
            />
          </label>

          <label>
            Email Address
            <input
              type="email"
              name="email"
              placeholder="you@example.com"
              value={form.email}
              onChange={handleChange}
              autoComplete="email"
              required
            />
          </label>

          <label>
            I want to join as
            <select
              name="role"
              value={form.role}
              onChange={handleChange}
            >
              <option value="customer">Customer</option>
              <option value="artisan">Artisan / Seller</option>
            </select>
          </label>

          <label>
            Password
            <div className="auth-password">
              <input
                type={showPassword ? 'text' : 'password'}
                name="password"
                placeholder="At least 8 characters"
                value={form.password}
                onChange={handleChange}
                autoComplete="new-password"
                minLength={8}
                required
              />

              <button
                type="button"
                className="auth-eye"
                onClick={() => setShowPassword(!showPassword)}
                aria-label={showPassword ? 'Hide password' : 'Show password'}
              >
                {showPassword ? <EyeOff size={19} /> : <Eye size={19} />}
              </button>
            </div>
          </label>

          <label>
            Confirm Password
            <div className="auth-password">
              <input
                type={showConfirmPassword ? 'text' : 'password'}
                name="confirmPassword"
                placeholder="Enter your password again"
                value={form.confirmPassword}
                onChange={handleChange}
                autoComplete="new-password"
                required
              />

              <button
                type="button"
                className="auth-eye"
                onClick={() =>
                  setShowConfirmPassword(!showConfirmPassword)
                }
                aria-label={
                  showConfirmPassword ? 'Hide password' : 'Show password'
                }
              >
                {showConfirmPassword ? <EyeOff size={19} /> : <Eye size={19} />}
              </button>
            </div>
          </label>

          {error && (
            <p className="auth-message" role="alert">
              {error}
            </p>
          )}

          <button type="submit" className="auth-submit">
            Create Account <ArrowRight size={18} />
          </button>
        </form>

        <p className="auth-switch">
          Already have an account? <Link to="/login">Sign In</Link>
        </p>

        <div className="auth-back">
          <Leaf size={15} />
          <Link to="/">Back to CraftLanka</Link>
        </div>
      </section>

      <aside className="auth-visual">
        <div className="auth-visual-overlay">
          <p>CELEBRATING SRI LANKAN CREATIVITY</p>
          <h2>Discover. Connect. Celebrate.</h2>
          <span>
            Support local artisans and bring meaningful handmade creations
            into your life.
          </span>
        </div>
      </aside>
    </main>
  );
}

export default Signup;
